import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

interface VendorBody {
  id: string;
  name: string;
  status: string;
}

interface DocumentBody {
  id: string;
  kind: string;
  status: string;
}

interface ExtractionBody {
  id: string;
  document_id: string;
  kind: string;
  status: string;
}

const TAG = "@LIF-09";

function uniqueSuffix(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function pollForExtraction(
  api: APIRequestContext,
  documentId: string,
  timeoutMs = 60_000,
): Promise<ExtractionBody> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const response = await api.get(`/api/documents/${documentId}/extraction`);
    if (response.status() === 200) {
      return (await response.json()) as ExtractionBody;
    }
    await new Promise((resolve) => setTimeout(resolve, 1_000));
  }
  throw new Error(`No extraction became available for document ${documentId} within ${timeoutMs}ms`);
}

test.describe("vendor lifecycle", () => {
  test(
    "a vendor that was sent back can be edited again",
    { tag: TAG },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor with a unique name and uploads a contract.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const suffix = uniqueSuffix();
      const originalName = `LIF-09 Vendor ${suffix}`;
      const newName = `LIF-09 Renamed ${suffix}`;

      const created = await expectStatus<VendorBody>(
        await member.post("/api/vendors", {
          data: {
            name: originalName,
            category: "services",
            contact_email: `ops-${suffix}@example.test`,
          },
        }),
        201,
      );

      const document = await expectStatus<DocumentBody>(
        await member.post(`/api/vendors/${created.id}/documents`, {
          multipart: {
            kind: "contract",
            file: {
              name: `contract-${suffix}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4 contract ${suffix}`),
            },
          },
        }),
        201,
      );
      expect(document.kind).toBe("contract");

      await expectStatus<VendorBody>(
        await member.post(`/api/vendors/${created.id}/submit`),
        200,
      );

      // Arrange: a reviewer rejects the contract extraction, sending the vendor back.
      const extraction = await pollForExtraction(member, document.id);
      expect(extraction.kind).toBe("contract");

      await expectStatus(
        await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
          data: { decision: "reject", note: `LIF-09 rejected ${suffix}` },
        }),
        200,
      );

      // Act: the member changes the vendor's name.
      const updated = await member.patch(`/api/vendors/${created.id}`, {
        data: { name: newName },
      });

      // Assert: the edit is accepted and the vendor carries the new name.
      const body = await expectStatus<VendorBody>(updated, 200);
      expect(body.name).toBe(newName);

      const fetched = await expectStatus<VendorBody>(
        await member.get(`/api/vendors/${created.id}`),
        200,
      );
      expect(fetched.name).toBe(newName);
    },
  );
});
